--
-- Name: bump_public_read_cache_generation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_public_read_cache_generation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE next_generation bigint;
        BEGIN
            IF TG_OP <> 'TRUNCATE' THEN
                IF NOT EXISTS (SELECT 1 FROM cache_changed_rows) THEN
                    RETURN NULL;
                END IF;
            END IF;
            UPDATE public.public_read_cache_generations
            SET generation = generation + 1 WHERE domain = 'trading'
            RETURNING generation INTO STRICT next_generation;
            INSERT INTO public.public_read_cache_events(domain,generation)
            VALUES ('trading',next_generation);
            DELETE FROM public.public_read_cache_events
            WHERE domain = 'trading'
                AND generation <= next_generation - 4096;
            PERFORM pg_notify('verdaxis_public_read_cache','trading');
            RETURN NULL;
        END $$;


--
-- Name: market_event_outbox_advance_replay_floor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.market_event_outbox_advance_replay_floor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
            owner_valid boolean;
            advanced_floor bigint;
        BEGIN
            SELECT control.mode = 'rust_active'
                   AND control.environment IS NOT NULL
                   AND control.environment <> ''
                   AND control.release_sha IS NOT NULL
                   AND control.selector_config_digest IS NOT NULL
                   AND control.drain_completed_at IS NOT NULL
              INTO owner_valid
              FROM public.market_event_retention_control AS control
             WHERE control.singleton
               FOR SHARE;

            IF NOT COALESCE(owner_valid, false) THEN
                RAISE EXCEPTION
                    'market_event_outbox delete is refused: retention ownership is not rust_active'
                    USING ERRCODE = '42501';
            END IF;

            IF OLD.stream_seq IS NULL THEN
                RAISE EXCEPTION
                    'market_event_outbox delete is refused for an unsequenced row'
                    USING ERRCODE = '23514';
            END IF;

            UPDATE public.market_event_replay_state
               SET discarded_through_seq = GREATEST(
                       discarded_through_seq, OLD.stream_seq
                   )
             WHERE singleton
            RETURNING discarded_through_seq INTO advanced_floor;

            IF advanced_floor IS NULL THEN
                RAISE EXCEPTION
                    'market_event_replay_state is missing; replay coverage is unavailable'
                    USING ERRCODE = '55000';
            END IF;

            RETURN OLD;
        END;
        $$;


