-- Name: verdaxis_immutable_org_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verdaxis_immutable_org_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            IF TG_OP = 'INSERT' THEN
                IF NEW.provenance = 'DEMO' AND NEW.id NOT IN (
                    SELECT value::uuid FROM unnest(ARRAY[
    '4da7b285-34ee-5443-9406-f96b4ed1a251',
    '0dbce576-2026-5925-ab66-674d505e98ad',
    '3cd0bc8a-0e92-5eb8-9ae3-3c87a7460a6a',
    '277491df-cb0d-5f2d-a2cf-5746829c6da6',
    '3b302066-d65c-5c3e-8fcc-70b3da3bcafd',
    '79609f48-0a3e-560e-a1e1-63d90601d84a',
    '2c4e387e-de22-5adb-ad88-9274ba84ebe1',
    '612953c7-567a-58b3-bc42-ee817d2bbe74',
    '93ccda09-54b3-53ee-afc0-759d3048161f',
    '82426590-0963-5486-9b05-f81e97afe6ef',
    'acc3f20a-fe94-4463-9029-a55e35634eb7',
    'c9c1ccbf-66fe-4a1b-b171-fe4f7ddc31a4',
    '7cc77115-0a9f-4ec4-8c74-05aa10050111',
    'd1e43e55-3fb0-4b5e-9f0b-93aa10050222'
]) AS value
                ) THEN
                    RAISE EXCEPTION 'DEMO provenance is restricted to deterministic seed identities';
                ELSIF NEW.provenance = 'TEST' AND NEW.id NOT IN (
                    SELECT value::uuid FROM unnest(ARRAY[
    '9e63f7a1-0000-4000-8000-000000000001',
    '9e63f7a1-0000-4000-8000-000000000002',
    '9e63f7a1-0000-4000-8000-000000000003',
    '9e63f7a1-0000-4000-8000-000000000004',
    '9e63f7a1-0000-4000-8000-000000000011',
    '9e63f7a1-0000-4000-8000-000000000012',
    '9e63f7a1-0000-4000-8000-000000000013',
    '9e63f7a1-0000-4000-8000-000000000014'
]) AS value
                ) THEN
                    RAISE EXCEPTION 'TEST provenance is restricted to deterministic test identities';
                ELSIF NEW.provenance = 'CANARY' THEN
                    RAISE EXCEPTION 'CANARY provenance requires an external security-owned registry';
                END IF;
            ELSIF OLD.provenance IS DISTINCT FROM NEW.provenance THEN
                IF NOT (
                    OLD.provenance = 'UNKNOWN'
                    AND NEW.provenance = 'REAL'
                    AND NEW.verification_status = 'APPROVED'
                    AND EXISTS (
                        SELECT 1 FROM organization_market_approvals
                        WHERE organization_id = NEW.id
                    )
                ) THEN
                    RAISE EXCEPTION 'organization provenance is immutable';
                END IF;
            END IF;
            
            -- Company approval is the trust decision. The trigger sets this
            -- field so the app still has no direct UPDATE grant on provenance.
            IF TG_OP = 'UPDATE'
                AND OLD.verification_status IS DISTINCT FROM NEW.verification_status
                AND NEW.verification_status = 'APPROVED'
                AND NEW.provenance = 'UNKNOWN'
                AND NEW.id NOT IN (
                    SELECT value::uuid FROM unnest(ARRAY[
    '4da7b285-34ee-5443-9406-f96b4ed1a251',
    '0dbce576-2026-5925-ab66-674d505e98ad',
    '3cd0bc8a-0e92-5eb8-9ae3-3c87a7460a6a',
    '277491df-cb0d-5f2d-a2cf-5746829c6da6',
    '3b302066-d65c-5c3e-8fcc-70b3da3bcafd',
    '79609f48-0a3e-560e-a1e1-63d90601d84a',
    '2c4e387e-de22-5adb-ad88-9274ba84ebe1',
    '612953c7-567a-58b3-bc42-ee817d2bbe74',
    '93ccda09-54b3-53ee-afc0-759d3048161f',
    '82426590-0963-5486-9b05-f81e97afe6ef',
    'acc3f20a-fe94-4463-9029-a55e35634eb7',
    'c9c1ccbf-66fe-4a1b-b171-fe4f7ddc31a4',
    '7cc77115-0a9f-4ec4-8c74-05aa10050111',
    'd1e43e55-3fb0-4b5e-9f0b-93aa10050222'
, 
    '9e63f7a1-0000-4000-8000-000000000001',
    '9e63f7a1-0000-4000-8000-000000000002',
    '9e63f7a1-0000-4000-8000-000000000003',
    '9e63f7a1-0000-4000-8000-000000000004',
    '9e63f7a1-0000-4000-8000-000000000011',
    '9e63f7a1-0000-4000-8000-000000000012',
    '9e63f7a1-0000-4000-8000-000000000013',
    '9e63f7a1-0000-4000-8000-000000000014'
]) AS value
                )
            THEN
                -- FILLED orders can reopen when a pending trade is declined.
                IF EXISTS (
                    SELECT 1 FROM orderbook_orders
                    WHERE organization_id = NEW.id
                        AND provenance = 'UNKNOWN'
                        AND status NOT IN ('CANCELLED', 'EXPIRED')
                ) THEN
                    RAISE EXCEPTION 'close unresolved UNKNOWN orders before company approval'
                        USING ERRCODE = 'VD001';
                END IF;
                NEW.provenance := 'REAL';
            END IF;
    
            RETURN NEW;
        END;
        $$;


--
-- Name: verdaxis_immutable_trade_fee_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verdaxis_immutable_trade_fee_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            BEGIN
                IF OLD.commission_fee_per_mt_usd IS DISTINCT FROM NEW.commission_fee_per_mt_usd
                    OR OLD.commission_plan IS DISTINCT FROM NEW.commission_plan
                    OR (
                        OLD.commission_fee_per_mt_usd IS NOT NULL
                        AND OLD.commission_rate_pct IS DISTINCT FROM NEW.commission_rate_pct
                    )
                THEN
                    RAISE EXCEPTION 'trade fee snapshot is immutable';
                END IF;
                RETURN NEW;
            END;
            $$;


--
-- Name: verdaxis_validate_accepted_rfq(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verdaxis_validate_accepted_rfq() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            DECLARE quote_row rfq_quotes%ROWTYPE;
            DECLARE trade_row trades%ROWTYPE;
            BEGIN
                IF NEW.status = 'ACCEPTED' THEN
                    SELECT * INTO STRICT quote_row FROM rfq_quotes WHERE id = NEW.accepted_quote_id;
                    SELECT * INTO STRICT trade_row FROM trades WHERE id = NEW.trade_id;
                    IF quote_row.rfq_id IS DISTINCT FROM NEW.id
                       OR quote_row.status IS DISTINCT FROM 'ACCEPTED'
                       OR trade_row.buyer_id IS DISTINCT FROM NEW.buyer_org_id
                       OR trade_row.seller_id IS DISTINCT FROM quote_row.seller_org_id
                       OR trade_row.product_id IS DISTINCT FROM NEW.product_id
                       OR trade_row.delivery_point_id IS DISTINCT FROM NEW.delivery_point_id
                       OR trade_row.availability_window IS DISTINCT FROM NEW.availability_window
                       OR trade_row.quantity_mt > NEW.quantity_mt
                       OR trade_row.price_per_mt_usd IS DISTINCT FROM quote_row.price_per_mt_usd THEN
                        RAISE EXCEPTION 'accepted RFQ, quote, and trade are inconsistent';
                    END IF;
                END IF;
                RETURN NEW;
            END;
            $$;


--
-- Name: verdaxis_validate_order_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verdaxis_validate_order_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            DECLARE expected_provenance text;
            BEGIN
                SELECT provenance INTO STRICT expected_provenance
                FROM organizations WHERE id = NEW.organization_id;
                IF NEW.provenance IS DISTINCT FROM expected_provenance THEN
                    RAISE EXCEPTION 'order provenance must equal owning organization provenance';
                END IF;
                IF TG_OP = 'UPDATE' AND (
                    OLD.organization_id IS DISTINCT FROM NEW.organization_id
                    OR OLD.provenance IS DISTINCT FROM NEW.provenance
                    OR OLD.side IS DISTINCT FROM NEW.side
                    OR OLD.product_id IS DISTINCT FROM NEW.product_id
                    OR OLD.delivery_point_id IS DISTINCT FROM NEW.delivery_point_id
                    OR OLD.availability_window IS DISTINCT FROM NEW.availability_window
                    OR OLD.inventory_item_id IS DISTINCT FROM NEW.inventory_item_id
                ) THEN
                    RAISE EXCEPTION 'order ownership, provenance, slice, and inventory snapshot are immutable';
                END IF;
                RETURN NEW;
            END;
            $$;


--
-- Name: verdaxis_validate_rfq_quote_party(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verdaxis_validate_rfq_quote_party() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            DECLARE buyer uuid;
            BEGIN
                SELECT buyer_org_id INTO STRICT buyer FROM rfqs WHERE id = NEW.rfq_id;
                IF NEW.seller_org_id = buyer THEN
                    RAISE EXCEPTION 'RFQ buyer and quote seller must differ';
                END IF;
                IF TG_OP = 'UPDATE' AND EXISTS (
                    SELECT 1 FROM rfqs
                    WHERE accepted_quote_id = OLD.id AND status = 'ACCEPTED'
                      AND (NEW.id IS DISTINCT FROM OLD.id
                           OR NEW.rfq_id IS DISTINCT FROM OLD.rfq_id
                           OR NEW.seller_org_id IS DISTINCT FROM OLD.seller_org_id
                           OR NEW.price_per_mt_usd IS DISTINCT FROM OLD.price_per_mt_usd
                           OR NEW.status IS DISTINCT FROM 'ACCEPTED')
                ) THEN
                    RAISE EXCEPTION 'accepted RFQ quote identity and economics are immutable';
                END IF;
                RETURN NEW;
            END;
            $$;


--
-- Name: verdaxis_validate_trade_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verdaxis_validate_trade_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
            DECLARE current_buyer_provenance text;
            DECLARE current_seller_provenance text;
            DECLARE product_row products%ROWTYPE;
            DECLARE delivery_point_row delivery_points%ROWTYPE;
            DECLARE expected_market_product text;
            BEGIN
                IF TG_OP = 'INSERT' THEN
                    SELECT provenance INTO STRICT current_buyer_provenance
                    FROM organizations WHERE id = NEW.buyer_id;
                    SELECT provenance INTO STRICT current_seller_provenance
                    FROM organizations WHERE id = NEW.seller_id;
                    IF NEW.buyer_provenance IS DISTINCT FROM current_buyer_provenance
                       OR NEW.seller_provenance IS DISTINCT FROM current_seller_provenance THEN
                        RAISE EXCEPTION 'trade provenance snapshots must equal current party provenance';
                    END IF;
                    IF NEW.market_snapshot_version IS DISTINCT FROM 1 THEN
                        RAISE EXCEPTION 'new trades require immutable market snapshot version 1';
                    END IF;
                    SELECT * INTO STRICT product_row
                    FROM products WHERE id = NEW.product_id;
                    expected_market_product := CASE WHEN product_row.id = 'c4cecebc-3d2d-5840-8021-57a9a11bc673' AND product_row.name = 'B30' AND product_row.fuel_type = 'Biofuel' AND product_row.fuel_grade = 'B30' THEN 'B30' WHEN product_row.id = '74eb9cb5-f0e3-55f1-b82c-fe29b7c45bf5' AND product_row.name = 'B100' AND product_row.fuel_type = 'Biofuel' AND product_row.fuel_grade = 'B100' THEN 'B100' WHEN product_row.id = '9510c713-6e39-5080-add3-0a7c29657b79' AND product_row.name = 'Bio Methanol' AND product_row.fuel_type = 'Methanol' AND product_row.fuel_grade = 'Bio' THEN 'BIO_METHANOL' WHEN product_row.id = 'f9b20492-b445-59cd-b292-a386d913f488' AND product_row.name = 'e-Methanol' AND product_row.fuel_type = 'Methanol' AND product_row.fuel_grade = 'E' THEN 'E_METHANOL' WHEN product_row.id = 'c4a688be-f7c2-5edc-8f93-6b34e387609c' AND product_row.name = 'Bio Ethanol' AND product_row.fuel_type = 'Ethanol' AND product_row.fuel_grade = 'Bio' THEN 'BIO_ETHANOL' WHEN product_row.id = 'd186bffb-766d-5944-8825-989abbdcfc46' AND product_row.name = 'Synthetic Ethanol' AND product_row.fuel_type = 'Ethanol' AND product_row.fuel_grade = 'Synthetic' THEN 'SYNTHETIC_ETHANOL' WHEN product_row.id = 'e561e43f-d9b2-598e-981c-f1d28d515ddc' AND product_row.name = 'UCOME B100' AND product_row.fuel_type = 'FAME' AND product_row.fuel_grade = 'UCOME' THEN 'UCOME_B100' WHEN product_row.id = '8f6f34a5-2927-54a6-8564-cca40ae7cb8a' AND product_row.name = 'Bio-LNG' AND product_row.fuel_type = 'LNG' AND product_row.fuel_grade = 'Bio' THEN 'BIO_LNG' ELSE NULL END;
                    IF product_row.is_active IS DISTINCT FROM true
                       OR expected_market_product IS NULL THEN
                        RAISE EXCEPTION 'trade product snapshot must reference an active canonical product';
                    END IF;
                    IF ROW(
                        NEW.product_name, NEW.fuel_type, NEW.fuel_grade,
                        NEW.market_product
                    ) IS DISTINCT FROM ROW(
                        product_row.name, product_row.fuel_type,
                        product_row.fuel_grade, expected_market_product
                    ) THEN
                        RAISE EXCEPTION 'trade product snapshot labels do not match referenced product';
                    END IF;
                    SELECT * INTO STRICT delivery_point_row
                    FROM delivery_points WHERE id = NEW.delivery_point_id;
                    IF delivery_point_row.is_active IS DISTINCT FROM true
                       OR NOT ((delivery_point_row.id = '78281fb3-e726-5396-802e-34b01fda21e8' AND delivery_point_row.name = 'Dalian' AND delivery_point_row.region = 'Asia') OR (delivery_point_row.id = '262d36ae-6f35-5785-b9e8-9e221b0f1b78' AND delivery_point_row.name = 'Busan' AND delivery_point_row.region = 'Asia') OR (delivery_point_row.id = '633c0593-f9b9-52ad-abe5-a0285f6888d3' AND delivery_point_row.name = 'Shanghai' AND delivery_point_row.region = 'Asia') OR (delivery_point_row.id = '73835e92-820e-584b-8280-bb61c63aa28e' AND delivery_point_row.name = 'Singapore' AND delivery_point_row.region = 'Asia') OR (delivery_point_row.id = '1379d36c-1ca9-55b7-9c0d-5235a0ba1f36' AND delivery_point_row.name = 'Rotterdam' AND delivery_point_row.region = 'Europe') OR (delivery_point_row.id = 'a083db06-b050-56c2-a274-3897eac2fdae' AND delivery_point_row.name = 'Houston' AND delivery_point_row.region = 'Americas') OR (delivery_point_row.id = '1be2a5cb-fc34-5e88-8b15-7f7d0fd6e534' AND delivery_point_row.name = 'Los Angeles' AND delivery_point_row.region = 'Americas') OR (delivery_point_row.id = 'a4762444-4e0b-5bc1-b647-a185047adae5' AND delivery_point_row.name = 'Santos' AND delivery_point_row.region = 'Americas')) THEN
                        RAISE EXCEPTION 'trade delivery snapshot must reference an active canonical delivery point';
                    END IF;
                    IF ROW(
                        NEW.delivery_point_name, NEW.delivery_point_region
                    ) IS DISTINCT FROM ROW(
                        delivery_point_row.name, delivery_point_row.region
                    ) THEN
                        RAISE EXCEPTION 'trade delivery snapshot labels do not match referenced delivery point';
                    END IF;
                    IF NEW.availability_window IS NULL OR NOT (
                        NEW.availability_window = 'SPOT'
                        OR NEW.availability_window ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'
                        OR NEW.availability_window ~ '^[0-9]{4}-Q[1-4]$'
                        OR NEW.availability_window ~ '^[0-9]{4}-CAL$'
                    ) THEN
                        RAISE EXCEPTION 'trade snapshot requires a canonical availability window';
                    END IF;
                    IF NOT (
                        (NEW.buyer_provenance = 'REAL' AND NEW.seller_provenance = 'REAL')
                        OR (NEW.buyer_provenance = 'DEMO' AND NEW.seller_provenance = 'DEMO'
                            AND NEW.buyer_id IN ('4da7b285-34ee-5443-9406-f96b4ed1a251','0dbce576-2026-5925-ab66-674d505e98ad','3cd0bc8a-0e92-5eb8-9ae3-3c87a7460a6a','277491df-cb0d-5f2d-a2cf-5746829c6da6','3b302066-d65c-5c3e-8fcc-70b3da3bcafd','79609f48-0a3e-560e-a1e1-63d90601d84a','2c4e387e-de22-5adb-ad88-9274ba84ebe1','612953c7-567a-58b3-bc42-ee817d2bbe74','93ccda09-54b3-53ee-afc0-759d3048161f','82426590-0963-5486-9b05-f81e97afe6ef','acc3f20a-fe94-4463-9029-a55e35634eb7','c9c1ccbf-66fe-4a1b-b171-fe4f7ddc31a4','7cc77115-0a9f-4ec4-8c74-05aa10050111','d1e43e55-3fb0-4b5e-9f0b-93aa10050222')
                            AND NEW.seller_id IN ('4da7b285-34ee-5443-9406-f96b4ed1a251','0dbce576-2026-5925-ab66-674d505e98ad','3cd0bc8a-0e92-5eb8-9ae3-3c87a7460a6a','277491df-cb0d-5f2d-a2cf-5746829c6da6','3b302066-d65c-5c3e-8fcc-70b3da3bcafd','79609f48-0a3e-560e-a1e1-63d90601d84a','2c4e387e-de22-5adb-ad88-9274ba84ebe1','612953c7-567a-58b3-bc42-ee817d2bbe74','93ccda09-54b3-53ee-afc0-759d3048161f','82426590-0963-5486-9b05-f81e97afe6ef','acc3f20a-fe94-4463-9029-a55e35634eb7','c9c1ccbf-66fe-4a1b-b171-fe4f7ddc31a4','7cc77115-0a9f-4ec4-8c74-05aa10050111','d1e43e55-3fb0-4b5e-9f0b-93aa10050222'))
