    CONSTRAINT ck_trades_lng_terms CHECK ((((product_id IS DISTINCT FROM '8f6f34a5-2927-54a6-8564-cca40ae7cb8a'::uuid) AND (lng_terms_snapshot IS NULL)) OR (((product_id = '8f6f34a5-2927-54a6-8564-cca40ae7cb8a'::uuid) AND (delivery_point_id = '1379d36c-1ca9-55b7-9c0d-5235a0ba1f36'::uuid) AND (delivery_point_id IS NOT NULL) AND (quantity_mt >= 0.01) AND (lng_terms_snapshot IS NOT NULL) AND ((json_typeof(lng_terms_snapshot) = 'object'::text) AND (((json_typeof((lng_terms_snapshot -> 'bid'::text)) = 'object'::text) AND (((lng_terms_snapshot -> 'bid'::text) ->> 'side'::text) = 'BID'::text)) IS TRUE) AND (((json_typeof((lng_terms_snapshot -> 'ask'::text)) = 'object'::text) AND (((lng_terms_snapshot -> 'ask'::text) ->> 'side'::text) = 'ASK'::text)) IS TRUE))) IS TRUE))),
    CONSTRAINT ck_trades_numeric_values CHECK (((quantity_mt IS NOT NULL) AND (quantity_mt >= 0.01) AND (quantity_mt <= 100000.00) AND ((quantity_mt * (100)::numeric) = trunc((quantity_mt * (100)::numeric))) AND (price_per_mt_usd IS NOT NULL) AND (price_per_mt_usd >= 0.01) AND (price_per_mt_usd <= 1000000.00) AND ((price_per_mt_usd * (100)::numeric) = trunc((price_per_mt_usd * (100)::numeric))) AND ((final_quantity_mt IS NULL) OR ((final_quantity_mt IS NOT NULL) AND (final_quantity_mt >= 0.01) AND (final_quantity_mt <= 100000.00) AND ((final_quantity_mt * (100)::numeric) = trunc((final_quantity_mt * (100)::numeric))))) AND ((final_price_per_mt IS NULL) OR ((final_price_per_mt IS NOT NULL) AND (final_price_per_mt >= 0.01) AND (final_price_per_mt <= 1000000.00) AND ((final_price_per_mt * (100)::numeric) = trunc((final_price_per_mt * (100)::numeric))))) AND ((final_total_usd IS NULL) OR ((final_total_usd IS NOT NULL) AND (final_total_usd >= (0)::numeric) AND (final_total_usd <= 100000000000.00) AND ((final_total_usd * (100)::numeric) = trunc((final_total_usd * (100)::numeric))))) AND (commission_rate_pct IS NOT NULL) AND (commission_rate_pct >= (0)::numeric) AND (commission_rate_pct <= (100)::numeric) AND ((commission_rate_pct * (1000)::numeric) = trunc((commission_rate_pct * (1000)::numeric))) AND ((commission_amount_usd IS NULL) OR ((commission_amount_usd IS NOT NULL) AND (commission_amount_usd >= (0)::numeric) AND (commission_amount_usd <= 100000000000.00) AND ((commission_amount_usd * (100)::numeric) = trunc((commission_amount_usd * (100)::numeric))))) AND ((commission_fee_per_mt_usd IS NULL) OR ((commission_fee_per_mt_usd IS NOT NULL) AND (commission_fee_per_mt_usd >= (0)::numeric) AND (commission_fee_per_mt_usd <= 100000.00) AND ((commission_fee_per_mt_usd * (100)::numeric) = trunc((commission_fee_per_mt_usd * (100)::numeric))))))),
    CONSTRAINT ck_trades_snapshot CHECK (((market_snapshot_version IS NULL) OR ((market_snapshot_version = 1) AND (product_id IS NOT NULL) AND (product_name IS NOT NULL) AND (TRIM(BOTH FROM product_name) <> ''::text) AND (fuel_type IS NOT NULL) AND (TRIM(BOTH FROM fuel_type) <> ''::text) AND (fuel_grade IS NOT NULL) AND (TRIM(BOTH FROM fuel_grade) <> ''::text) AND ((market_product)::text = ANY ((ARRAY['B30'::character varying, 'B100'::character varying, 'BIO_LNG'::character varying, 'UCOME_B100'::character varying, 'BIO_METHANOL'::character varying, 'E_METHANOL'::character varying, 'BIO_ETHANOL'::character varying, 'SYNTHETIC_ETHANOL'::character varying])::text[])) AND (availability_window IS NOT NULL) AND (((availability_window)::text = 'SPOT'::text) OR ((availability_window)::text ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'::text) OR ((availability_window)::text ~ '^[0-9]{4}-Q[1-4]$'::text) OR ((availability_window)::text ~ '^[0-9]{4}-CAL$'::text)) AND (delivery_point_id IS NOT NULL) AND (delivery_point_name IS NOT NULL) AND (delivery_point_region IS NOT NULL))))
);


