--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email character varying NOT NULL,
    password_hash character varying NOT NULL,
    first_name character varying,
    last_name character varying,
    role character varying(8),
    organization_id uuid,
    last_login timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    status character varying(8) DEFAULT 'PENDING'::character varying NOT NULL,
    password_changed_at timestamp with time zone,
    email_verified boolean DEFAULT false NOT NULL,
    kyc_status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    kyc_rejection_reason text,
    password_reset_token_hash character varying(64),
    password_reset_expires timestamp with time zone,
    referral_code character varying(10),
    referred_by_id uuid,
    onboarding_use_case character varying(50),
    onboarding_referral_source character varying(500),
    must_change_password boolean DEFAULT false NOT NULL,
    email_verification_token_hash character varying(64),
    email_verification_token_expires_at timestamp with time zone,
    kyc_external_evidence_reference character varying(200),
    kyc_review_note text,
    kyc_reviewed_by uuid,
    kyc_reviewed_at timestamp with time zone,
    kyc_organization_id uuid,
    pending_approval_email_transition_id uuid,
    pending_approval_email_payload jsonb,
    pending_approval_email_retry_at timestamp with time zone,
    authentication_revoked_at timestamp with time zone
);


