--
-- Name: watchlist_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.watchlist_events (
    id uuid NOT NULL,
    watchlist_id uuid NOT NULL,
    watchlist_target_id uuid NOT NULL,
    event_type character varying(32) NOT NULL,
    event_payload json DEFAULT '{}'::json NOT NULL,
    is_read boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    producer character varying(32) DEFAULT 'legacy-python'::character varying NOT NULL,
    source_event_id uuid,
    source_stream_seq bigint,
    scope_attested_at timestamp with time zone,
    derived_event_key character varying(255),
    CONSTRAINT ck_watchlist_events_producer_identity CHECK (((((producer)::text = 'legacy-python'::text) AND (source_event_id IS NULL) AND (source_stream_seq IS NULL) AND (scope_attested_at IS NULL) AND (derived_event_key IS NULL)) OR (((producer)::text = 'rust-market-v1'::text) AND (source_event_id IS NOT NULL) AND (source_stream_seq IS NOT NULL) AND (scope_attested_at IS NOT NULL) AND (derived_event_key IS NOT NULL) AND (char_length((derived_event_key)::text) > 0)))),
    CONSTRAINT watchlist_events_producer_check CHECK (((producer)::text = ANY ((ARRAY['legacy-python'::character varying, 'rust-market-v1'::character varying])::text[])))
);


--
-- Name: watchlist_producer_state; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.watchlist_producer_state (
    singleton boolean NOT NULL,
    consumed_through_seq bigint DEFAULT '0'::bigint NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT watchlist_producer_state_consumed_through_seq_check CHECK ((consumed_through_seq >= 0)),
    CONSTRAINT watchlist_producer_state_singleton_check CHECK (singleton)
);


--
-- Name: watchlist_targets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.watchlist_targets (
    id uuid NOT NULL,
    watchlist_id uuid NOT NULL,
    target_type character varying(16) NOT NULL,
    market_product_code character varying(64),
    delivery_point_id uuid,
    availability_window_code character varying(32),
    order_id uuid,
    snapshot_price_per_mt_usd double precision,
    snapshot_quantity_mt double precision,
    snapshot_remaining_quantity_mt double precision,
    snapshot_status character varying(32),
    snapshot_side character varying(8),
    snapshot_market_product character varying(64),
    snapshot_delivery_point_name character varying(120),
    snapshot_availability_window character varying(32),
    snapshot_counterparty_label character varying(120),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_watchlist_targets_valid_shape CHECK (((((target_type)::text = 'SLICE'::text) AND (order_id IS NULL) AND (market_product_code IS NOT NULL) AND (delivery_point_id IS NOT NULL) AND (availability_window_code IS NOT NULL)) OR (((target_type)::text = 'PIN'::text) AND (order_id IS NOT NULL) AND (market_product_code IS NOT NULL) AND (delivery_point_id IS NOT NULL) AND (availability_window_code IS NOT NULL))))
);


